Index: backend/tests/Feature/DivarProcessorTest.php
===================================================================
--- backend/tests/Feature/DivarProcessorTest.php	
+++ backend/tests/Feature/DivarProcessorTest.php	
@@ -0,0 +1,112 @@
+<?php
+
+namespace Tests\Feature;
+
+use Tests\TestCase;
+use App\Providers\Processors\DivarProcessor;
+use App\Providers\DTOs\{
+    ProductReference,
+    ProviderProductSnapshot,
+    NormalizedProductData
+};
+use Illuminate\Support\Facades\Http;
+use Illuminate\Foundation\Testing\RefreshDatabase;
+
+class DivarProcessorTest extends TestCase
+{
+    protected DivarProcessor $processor;
+
+    protected function setUp(): void
+    {
+        parent::setUp();
+        $this->processor = new DivarProcessor();
+    }
+
+    public function test_it_supports_divar_urls(): void
+    {
+        $this->assertTrue($this->processor->supports('https://divar.ir/v/12345/iphone-14-pro/'));
+        $this->assertTrue($this->processor->supports('http://divar.ir/v/67890/iphone-14/'));
+    }
+
+    public function test_it_does_not_support_non_divar_urls(): void
+    {
+        // These URLs should NOT be supported by divar processor
+        $this->assertFalse($this->processor->supports('https://torob.com/p/12345'));
+        $this->assertFalse($this->processor->supports('https://example.com/product'));
+        $this->assertFalse($this->processor->supports('https://other-market.com/v/12345'));
+    }
+
+    public function test_it_parses_divar_url_correctly(): void
+    {
+        $url = 'https://divar.ir/v/12345/iphone-14-pro-max-review/';
+        $reference = $this->processor->parseProductReference($url);
+
+        $this->assertInstanceOf(ProductReference::class, $reference);
+        $this->assertEquals('divar', $reference->provider);
+        $this->assertEquals('12345', $reference->externalId);
+    }
+
+    public function test_it_fetches_and_normalizes_product_data(): void
+    {
+        $reference = ProductReference::create('divar', '12345', 'iphone-14-pro');
+
+        Http::fake([
+            'divar.ir/*' => Http::response([
+                'data' => [
+                    'title' => 'آیفون ۱۴ پرو',
+                    'brand' => 'Apple',
+                    'model' => 'iPhone 14 Pro'
+                ],
+                'price' => [
+                    'amount' => 9500000,
+                    'currency' => 'IRR',
+                    'display' => '۹.۵ میلیون تومان'
+                ],
+                'availability' => 'available',
+                'stock_status' => 'موجود',
+                'seller' => [
+                    'name' => 'فروشگاه تکنولوژی',
+                    'url' => 'https://divar.ir/seller/123'
+                ]
+            ], 200)
+        ]);
+
+        $snapshot = $this->processor->fetchProduct($reference);
+        $this->assertInstanceOf(ProviderProductSnapshot::class, $snapshot);
+
+        $normalized = $this->processor->normalizeSnapshot($snapshot);
+
+        $this->assertEquals('divar', $normalized->provider);
+        $this->assertEquals('12345', $normalized->externalId);
+        $this->assertEquals('آیفون ۱۴ پرو', $normalized->title);
+        $this->assertEquals(9500000, $normalized->price['amount']);
+        $this->assertEquals('IRR', $normalized->price['currency']);
+        $this->assertEquals('available', $normalized->availability);
+    }
+
+    public function test_it_handles_unavailable_products(): void
+    {
+        $reference = ProductReference::create('divar', '67890', 'out-of-stock-item');
+
+        Http::fake([
+            'divar.ir/*' => Http::response([
+                'data' => [
+                    'title' => 'محصول ناموجود',
+                ],
+                'price' => [
+                    'amount' => 0,
+                    'currency' => 'IRR'
+                ],
+                'availability' => 'unavailable',
+                'stock_status' => 'ناموجود'
+            ], 200)
+        ]);
+
+        $normalized = $this->processor->normalizeSnapshot(
+            $this->processor->fetchProduct($reference)
+        );
+
+        $this->assertEquals('unavailable', $normalized->availability);
+        $this->assertEquals('ناموجود', $normalized->stockStatus);
+    }
+}
